module goat_rope_solver (input clk, input rst_n, input start, input [2:0] num_posts, input [31:0] post_x [0:7], input [31:0] post_y [0:7], output reg [31:0] result, output reg done);localparam IDLE = 3'd0, INIT_PAIRS = 3'd1, COMPUTE_DIST = 3'd2, FIND_MIN = 3'd3, DIVIDE = 3'd4, ROUND = 3'd5, DONE = 3'd6;reg [2:0] state, next_state;reg [31:0] min_distance, temp_result, dx, dy, dx_sq, dy_sq, sum_sq, distance;reg [7:0] i_cnt, j_cnt;reg [7:0] total_pairs;reg [31:0] post_x_reg [0:7], post_y_reg [0:7];reg [1:0] round_temp;output reg [31:0] result;output reg done;always @(posedge clk) begin if (!rst_n) begin state <= IDLE; min_distance <= 32'hFFFFFFFF; i_cnt <= 8'd0; j_cnt <= 8'd0; total_pairs <= 8'd0; post_x_reg <= 32'd0; post_y_reg <= 32'd0; result <= 32'd0; done <= 1'b0; dx <= 32'd0; dy <= 32'd0; end else begin state <= next_state; if (state == INIT_PAIRS) begin post_x_reg <= post_x; post_y_reg <= post_y; total_pairs <= (num_posts > 1) ? (num_posts*(num_posts-1) >> 1) : 8'd0; if (total_pairs == 8'd0) begin next_state <= DIVIDE; end else begin i_cnt <= 8'd0; j_cnt <= i_cnt + 1; next_state <= COMPUTE_DIST; end end else if (state == COMPUTE_DIST) begin dx = post_x_reg[i_cnt] - post_x_reg[j_cnt]; dy = post_y_reg[i_cnt] - post_y_reg[j_cnt]; dx_sq = dx * dx; dy_sq = dy * dy; sum_sq = dx_sq + dy_sq; distance = sum_sq >> 16; if (distance < min_distance) begin min_distance <= distance; end if (j_cnt < num_posts - 1) begin j_cnt <= j_cnt + 1; end else begin i_cnt <= i_cnt + 1; if (i_cnt < num_posts - 1) begin j_cnt <= i_cnt + 1; end else begin next_state <= FIND_MIN; end end next_state <= COMPUTE_DIST; end else if (state == FIND_MIN) begin next_state <= DIVIDE; end else if (state == DIVIDE) begin temp_result = min_distance >> 1; next_state <= ROUND; end else if (state == ROUND) begin round_temp = temp_result & 32'h8000; temp_result = (temp_result + 32'h8000) >> 1; result <= temp_result; next_state <= DONE; end end endalways @(*) begin next_state = state; done = (state == DONE); if (state == IDLE) begin if (start) next_state = INIT_PAIRS; end end end endmodule